package main
import "github.com/gofiber/fiber/v2"
func main() {
app := fiber.New()
type Book struct { Title string `json:"title"` }
app.Post("/books", func(c *fiber.Ctx) error { var book Book; if err := c.BodyParser(&book); err != nil || book.Title == "" { return c.Status(400).JSON(fiber.Map{"error": "Title needed"}) }; return c.Status(201).JSON(book) })
app.Listen("127.0.0.1:3000")
}
